/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92040.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);

        // 초기1회 초기값으로 설정된 지수업종코드를 검색한다.
        if (scwin.strSch !== "") {
            for (let i = 1; i <= dts_List.getRowCount(); i++) {
                // if (strSch == dts_List.ColumnString(i, 1))  { // 찾아야할 코드를 발견했을 경우
                if (scwin.strSch.substring(0, 13) === dts_List.getCellData(i, "IDX_TOTAL_CD").substring(0, 13)) // 찾아야할 코드를 발견했을 경우(STRT_DD제외)

                {
                    dts_List.setRowPosition(i, 0);
                    break;
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92040.dts_List_OnLoadCompleted" });
    }
};

/**
